-- Generated by scripts/build_osi.py from the ontology. Do not edit.
CREATE OR REPLACE SEMANTIC VIEW GLP.SEMANTIC.DIABETES_MARKET
  TABLES (
    prescription AS GLP.SEMANTIC.SV_PRESCRIPTION PRIMARY KEY (PRESCRIPTION_ID)
      WITH SYNONYMS = ('prescription aggregate', '処方集計', '处方汇总')
      COMMENT = 'The total Part D claims, fills, days of supply, cost and beneficiaries of one healthcare professional for one medicinal product in one data year. One row of the CMS ''Prescribers by Provider and Drug'' dataset.',
    prescription_class AS GLP.SEMANTIC.SV_PRESCRIPTION_CLASS PRIMARY KEY (PRESCRIPTION_ID, CLASS_ID)
      COMMENT = 'Claims attributed to therapeutic classes: one row per prescription and class of any of the product''s substances, including all broader classes (skos:broader*). A combination product counts in each of its classes, so never add claims across classes; filter or group by one class.',
    prescription_class_company AS GLP.SEMANTIC.SV_PRESCRIPTION_CLASS_COMPANY PRIMARY KEY (PRESCRIPTION_ID, CLASS_ID, ORGANIZATION_KEY)
      COMMENT = 'Claims by therapeutic class and manufacturer, for market shares: one row per prescription, class and marketing authorization holder. Unbranded generics have no single manufacturer. A product with two holders (Byetta) counts for each.',
    prescriber AS GLP.SEMANTIC.SV_PRESCRIBER PRIMARY KEY (PRESCRIBER_ID)
      WITH SYNONYMS = ('healthcare professional', '医療従事者', '医疗专业人员')
      COMMENT = 'An individual (NPI type 1) who prescribes drugs reimbursed under Medicare Part D.',
    specialty AS GLP.SEMANTIC.SV_SPECIALTY PRIMARY KEY (SPECIALTY_CODE)
      COMMENT = 'A concept from the NUCC Health Care Provider Taxonomy, published as a SKOS concept scheme. Joined as the prescriber''s primary specialty (NPI Registry).',
    product AS GLP.SEMANTIC.SV_PRODUCT PRIMARY KEY (PRODUCT_ID)
      WITH SYNONYMS = ('医薬品', '药品')
      COMMENT = 'A drug product as named in claims data: in Part D (CMS Brnd_Name, e.g. Jardiance; unbranded generics appear under their generic name), or in NDB Open Data, where each strength is its own product with a receipt code and a YJ code (e.g. ジャディアンス錠10mg).',
    therapeutic_class AS GLP.SEMANTIC.SV_THERAPEUTIC_CLASS PRIMARY KEY (CLASS_ID)
      COMMENT = 'A concept in the therapeutic class scheme (e.g. SGLT2 inhibitors). The hierarchy itself is maintained as a SKOS concept scheme, not as OWL subclasses.',
    organization AS GLP.SEMANTIC.SV_ORGANIZATION PRIMARY KEY (ORGANIZATION_ID)
      COMMENT = 'A company that holds the marketing authorization for a medicinal product: in the US the corporate group of the Drugs@FDA application holder (e.g. Boehringer Ingelheim), in Japan the holder named in the NHI price list (e.g. 日本ベーリンガーインゲルハイム).'
  )
  RELATIONSHIPS (
    prescription_to_prescriber AS prescription (PRESCRIBER_ID) REFERENCES prescriber (PRESCRIBER_ID),
    prescription_to_product AS prescription (PRODUCT_ID) REFERENCES product (PRODUCT_ID),
    prescriber_to_specialty AS prescriber (PRIMARY_SPECIALTY_CODE) REFERENCES specialty (SPECIALTY_CODE),
    prescription_class_to_prescription AS prescription_class (PRESCRIPTION_ID) REFERENCES prescription (PRESCRIPTION_ID),
    prescription_class_to_therapeutic_class AS prescription_class (CLASS_ID) REFERENCES therapeutic_class (CLASS_ID),
    prescription_class_company_to_prescription AS prescription_class_company (PRESCRIPTION_ID) REFERENCES prescription (PRESCRIPTION_ID),
    prescription_class_company_to_therapeutic_class AS prescription_class_company (CLASS_ID) REFERENCES therapeutic_class (CLASS_ID),
    prescription_class_company_to_organization AS prescription_class_company (ORGANIZATION_ID) REFERENCES organization (ORGANIZATION_ID)
  )
  FACTS (
    prescription.claims AS prescription.CLAIMS
      COMMENT = 'Number of Part D claims, including refills (CMS Tot_Clms).',
    prescription.fills_30day AS prescription.FILLS_30DAY
      COMMENT = 'Claims standardized to 30-day fills; a 90-day fill counts as 3.0 (CMS Tot_30day_Fills).',
    prescription.day_supply AS prescription.DAY_SUPPLY
      COMMENT = 'Total day supply.',
    prescription.drug_cost AS prescription.DRUG_COST
      COMMENT = 'Aggregate gross drug cost paid by Part D plan, beneficiary and other payers, in US dollars (CMS Tot_Drug_Cst).',
    prescription.beneficiaries AS prescription.BENEFICIARIES
      WITH SYNONYMS = ('total beneficiaries', '受給者数', '受益人数')
      COMMENT = 'Number of distinct Medicare beneficiaries (CMS Tot_Benes). Absent when 1-10, to protect privacy.',
    prescription_class.claims AS prescription_class.CLAIMS
      COMMENT = 'Number of Part D claims, including refills (CMS Tot_Clms).',
    prescription_class.fills_30day AS prescription_class.FILLS_30DAY
      COMMENT = 'Claims standardized to 30-day fills; a 90-day fill counts as 3.0 (CMS Tot_30day_Fills).',
    prescription_class.drug_cost AS prescription_class.DRUG_COST
      COMMENT = 'Aggregate gross drug cost paid by Part D plan, beneficiary and other payers, in US dollars (CMS Tot_Drug_Cst).',
    prescription_class_company.claims AS prescription_class_company.CLAIMS
      COMMENT = 'Number of Part D claims, including refills (CMS Tot_Clms).',
    prescription_class_company.claims_allocated AS prescription_class_company.CLAIMS_ALLOCATED
      COMMENT = 'Claims divided equally among the product''s marketing authorization holders, so that the companies of a class add up to the class''s claims. Use for market shares.',
    prescription_class_company.drug_cost AS prescription_class_company.DRUG_COST
      COMMENT = 'Aggregate gross drug cost paid by Part D plan, beneficiary and other payers, in US dollars (CMS Tot_Drug_Cst).'
  )
  DIMENSIONS (
    prescription.prescription_id AS prescription.PRESCRIPTION_ID
      COMMENT = 'Key: data year / prescriber / product.',
    prescription.prescriber_id AS prescription.PRESCRIBER_ID
      COMMENT = 'Pseudonymous prescriber key.',
    prescription.product_id AS prescription.PRODUCT_ID
      COMMENT = 'Product key.',
    prescription.data_year AS prescription.DATA_YEAR
      WITH SYNONYMS = ('データ年', '数据年份')
      COMMENT = 'Data year. Only 2024 is loaded.',
    prescription.beneficiaries_suppressed AS prescription.BENEFICIARIES_SUPPRESSED
      WITH SYNONYMS = ('beneficiary count suppressed', '受給者数秘匿', '受益人数已隐去')
      COMMENT = 'Beneficiary count suppressed.',
    prescription_class.prescription_id AS prescription_class.PRESCRIPTION_ID
      COMMENT = 'Prescription key.',
    prescription_class.class_id AS prescription_class.CLASS_ID
      COMMENT = 'Therapeutic class key.',
    prescription_class_company.prescription_id AS prescription_class_company.PRESCRIPTION_ID
      COMMENT = 'Prescription key.',
    prescription_class_company.class_id AS prescription_class_company.CLASS_ID
      COMMENT = 'Therapeutic class key.',
    prescription_class_company.manufacturer AS prescription_class_company.MANUFACTURER
      WITH SYNONYMS = ('manufactured by')
      COMMENT = 'Manufactured by. Company name, or ''generic (no single manufacturer)''.',
    prescriber.prescriber_id AS prescriber.PRESCRIBER_ID
      WITH SYNONYMS = ('pseudonymous ID', '仮名ID', '假名化ID')
      COMMENT = 'First 16 hex characters of HMAC-SHA256(secret key, NPI). Stable across runs with the same key; not reversible without it.',
    prescriber.cms_prescriber_type AS prescriber.CMS_PRESCRIBER_TYPE
      WITH SYNONYMS = ('CMS処方医区分', 'CMS处方者类别')
      COMMENT = 'Specialty as reported by CMS (Prscrbr_Type), a free-text label that differs from the NUCC code.',
    prescriber.city AS prescriber.CITY
      WITH SYNONYMS = ('市区町村', '城市')
      COMMENT = 'City.',
    prescriber.state AS prescriber.STATE
      WITH SYNONYMS = ('州')
      COMMENT = 'State.',
    prescriber.is_sglt2_prescriber AS prescriber.IS_SGLT2_PRESCRIBER
      WITH SYNONYMS = ('SGLT2 inhibitor prescriber', 'SGLT2阻害薬処方医', 'SGLT2抑制剂处方者')
      COMMENT = 'A healthcare professional who wrote at least one prescription for a product containing a substance in the SGLT2 inhibitor class.',
    prescriber.is_glp1_prescriber AS prescriber.IS_GLP1_PRESCRIBER
      WITH SYNONYMS = ('GLP-1 receptor agonist prescriber', 'GLP-1受容体作動薬処方医', 'GLP-1受体激动剂处方者')
      COMMENT = 'A healthcare professional who wrote at least one prescription for a product containing a substance in the GLP-1 receptor agonist class (including narrower classes such as dual GIP/GLP-1 agonists).',
    specialty.specialty_code AS specialty.SPECIALTY_CODE
      COMMENT = 'NUCC taxonomy code, e.g. 207RE0101X.',
    specialty.specialty_name AS specialty.SPECIALTY_NAME
      WITH SYNONYMS = ('specialty')
      COMMENT = 'Specialty name in English.',
    specialty.specialty_name_ja AS specialty.SPECIALTY_NAME_JA
      WITH SYNONYMS = ('専門分野')
      COMMENT = 'Specialty name in Japanese. English name where no Japanese label exists yet. Values: インターベンション循環器内科医; ナースプラクティショナー; フィジシャン・アシスタント; プライマリ・ケア・ナースプラクティショナー; ホスピタリスト; 内分泌・糖尿病・代謝内科医; 内科医; 内科系フィジシャン・アシスタント; 医療系教育・研修プログラム在籍者; 家庭医; 家庭医療ナースプラクティショナー; 循環器内科医; 急性期ナースプラクティショナー; 感染症内科医; 成人医療ナースプラクティショナー; 精神科ナースプラクティショナー; 精神科医; 老年内科医; 老年医療ナースプラクティショナー; 腎臓内科医.',
    specialty.specialty_name_zh AS specialty.SPECIALTY_NAME_ZH
      WITH SYNONYMS = ('专科')
      COMMENT = 'Specialty name in Chinese. English name where no Chinese label exists yet.',
    product.product_id AS product.PRODUCT_ID
      COMMENT = 'Product key.',
    product.brand_name AS product.BRAND_NAME
      WITH SYNONYMS = ('medicinal product')
      COMMENT = 'Medicinal product name in English. Values: Alogliptin; Basaglar Kwikpen U-100; Bydureon Bcise; Byetta; Dapagliflozin; Farxiga; Glimepiride; Glipizide; Glipizide Er; Glipizide Xl; Glipizide-Metformin; Glyburide; Glyxambi; Insulin Glargine Solostar; Insulin Glargine-Yfgn; Invokamet; Invokana; Janumet; Janumet Xr; Januvia; Jardiance; Jentadueto; Jentadueto Xr; Lantus; Lantus Solostar; Liraglutide; Metformin Er Gastric; Metformin Er Osmotic; Metformin Hcl; Metformin Hcl Er; Mounjaro; Ozempic; Pioglitazone Hcl; Pioglitazone-Metformin; Rybelsus; Saxagliptin Hcl; Semglee (Yfgn) Pen; Soliqua 100-33; Steglatro; Synjardy; Synjardy Xr; Toujeo Max Solostar; Toujeo Solostar; Tradjenta; Trijardy Xr; Trulicity; Victoza 2-Pak; Victoza 3-Pak; Wegovy; Xigduo Xr; Xultophy 100-3.6.',
    product.cms_generic_name AS product.CMS_GENERIC_NAME
      WITH SYNONYMS = ('CMS一般名', 'CMS通用名')
      COMMENT = 'Generic name exactly as spelled in the CMS data (Gnrc_Name), e.g. ''Dapaglifloz Propaned/Metformin''.',
    product.is_combination AS product.IS_COMBINATION
      WITH SYNONYMS = ('is combination product', '配合剤', '复方制剂')
      COMMENT = 'Is combination product.',
    product.is_sglt2_product AS product.IS_SGLT2_PRODUCT
      WITH SYNONYMS = ('SGLT2 inhibitor product', 'SGLT2阻害薬製剤', 'SGLT2抑制剂产品')
      COMMENT = 'A medicinal product containing a substance in the SGLT2 inhibitor class, alone or in combination.',
    product.is_glp1_product AS product.IS_GLP1_PRODUCT
      WITH SYNONYMS = ('GLP-1 receptor agonist product', 'GLP-1受容体作動薬製剤', 'GLP-1受体激动剂产品')
      COMMENT = 'A medicinal product containing a substance in the GLP-1 receptor agonist class (including dual GIP/GLP-1 agonists), alone or in combination, whatever its Japanese therapeutic category (249 or 396).',
    therapeutic_class.class_id AS therapeutic_class.CLASS_ID
      COMMENT = 'Class key, e.g. SGLT2Inhibitor.',
    therapeutic_class.class_name AS therapeutic_class.CLASS_NAME
      WITH SYNONYMS = ('therapeutic class')
      COMMENT = 'Therapeutic class name in English. Values: Alpha glucosidase inhibitors; Biguanides; Blood glucose lowering drugs, excl. insulins; Dipeptidyl peptidase 4 (DPP-4) inhibitors; Drugs used in diabetes; Glimins; Glinides; Glucagon-like peptide-1 (GLP-1) analogues; Glucose-dependent Insulinotropic Polypeptide Receptor Agonists; Insulins and analogues; Insulins and analogues for injection, fast-acting; Insulins and analogues for injection, intermediate- or long-acting combined with fast-acting; Insulins and analogues for injection, intermediate-acting; Insulins and analogues for injection, long-acting; Sodium-glucose co-transporter 2 (SGLT2) inhibitors; Sulfonylureas; Thiazolidinediones.',
    therapeutic_class.class_name_ja AS therapeutic_class.CLASS_NAME_JA
      WITH SYNONYMS = ('薬効群', 'ATC分類')
      COMMENT = 'Therapeutic class name in Japanese. Values: DPP-4阻害薬; GLP-1受容体作動薬; SGLT2阻害薬; α-グルコシダーゼ阻害薬; インスリン製剤; グリミン系薬; スルホニルウレア薬; チアゾリジン薬; ビグアナイド薬; 中間型インスリン; 持効型溶解インスリン; 持続性GIP/GLP-1受容体作動薬; 混合型インスリン; 糖尿病治療薬; 血糖降下薬（インスリンを除く）; 速効型インスリン分泌促進薬; 速効型・超速効型インスリン.',
    therapeutic_class.class_name_zh AS therapeutic_class.CLASS_NAME_ZH
      WITH SYNONYMS = ('治疗类别')
      COMMENT = 'Therapeutic class name in Chinese. Values: DPP-4抑制剂; GIP/GLP-1双受体激动剂; GLP-1受体激动剂; SGLT2抑制剂; α-葡萄糖苷酶抑制剂; 中效胰岛素; 双胍类药物; 噻唑烷二酮类药物; 格列奈类药物; 格列明类药物; 磺酰脲类药物; 糖尿病治疗药物; 胰岛素及其类似物; 速效胰岛素; 长效胰岛素; 降血糖药（不含胰岛素）; 预混胰岛素.',
    therapeutic_class.atc_code AS therapeutic_class.ATC_CODE
      COMMENT = 'ATC code of the class, e.g. A10BK. Glinides and imeglimin have none.',
    therapeutic_class.class_depth AS therapeutic_class.CLASS_DEPTH
      COMMENT = 'Level in the class tree (skos:broader*): 1 drugs used in diabetes, 2 insulins or blood glucose lowering drugs, 3 drug classes such as SGLT2 inhibitors, 4 narrower classes such as dual GIP/GLP-1 agonists, which also count in their broader class.',
    therapeutic_class.is_drug_class AS therapeutic_class.IS_DRUG_CLASS
      COMMENT = 'TRUE for the drug classes (SGLT2 inhibitors, GLP-1 receptor agonists, DPP-4 inhibitors, biguanides, long-acting insulins, ...): use it whenever a question says ''by drug class'' or ''by class'', so that broader and narrower classes are not listed next to them.',
    organization.organization_id AS organization.ORGANIZATION_ID
      COMMENT = 'LEI of the GLEIF ultimate parent, or a local id.',
    organization.company_name AS organization.COMPANY_NAME
      WITH SYNONYMS = ('organization')
      COMMENT = 'Organization name in English. Legal name of the ultimate parent in GLEIF. Values: AMYLIN (also: Amylin Pharmaceuticals); ASTRAZENECA PLC (also: AstraZeneca AB); C.H. Boehringer Sohn AG & Co. KG (also: Boehringer Ingelheim Pharmaceuticals, Inc.); ELI LILLY AND COMPANY; Johnson & Johnson (also: Janssen Pharmaceuticals, Inc.); MERCK & CO., INC. (also: Merck Sharp & Dohme LLC); NOVO NORDISK A/S (also: Novo Nordisk Inc.); SANOFI (also: Sanofi-Aventis U.S. LLC, Sanofi US Services Inc.); VIATRIS INC. (also: Mylan Pharmaceuticals Inc.).',
    organization.company_name_ja AS organization.COMPANY_NAME_JA
      WITH SYNONYMS = ('組織')
      COMMENT = 'Organization name in Japanese. Values: MSD; アストラゼネカ; アミリン・ファーマシューティカルズ; イーライリリー・アンド・カンパニー; サノフィ; ジョンソン・エンド・ジョンソン; ノボノルディスク; ベーリンガーインゲルハイム; ヴィアトリス.',
    organization.company_name_zh AS organization.COMPANY_NAME_ZH
      WITH SYNONYMS = ('组织')
      COMMENT = 'Organization name in Chinese.'
  )
  METRICS (
    total_claims AS SUM(prescription.claims)
      WITH SYNONYMS = ('total claims', '処方件数', '处方次数')
      COMMENT = 'Number of Part D claims, including refills (CMS Tot_Clms). All Part D claims.',
    total_drug_cost AS SUM(prescription.drug_cost)
      WITH SYNONYMS = ('total drug cost (USD)', '薬剤費総額（米ドル）', '药品总费用（美元）')
      COMMENT = 'Aggregate gross drug cost paid by Part D plan, beneficiary and other payers, in US dollars (CMS Tot_Drug_Cst). All gross drug cost in USD.',
    total_30day_fills AS SUM(prescription.fills_30day)
      WITH SYNONYMS = ('total 30-day fills', '30日換算処方数', '30天折算处方数')
      COMMENT = 'Claims standardized to 30-day fills; a 90-day fill counts as 3.0 (CMS Tot_30day_Fills).',
    total_day_supply AS SUM(prescription.day_supply)
      WITH SYNONYMS = ('total day supply', '総処方日数', '总供药天数'),
    cost_per_claim AS SUM(prescription.drug_cost) / NULLIF(SUM(prescription.claims), 0)
      COMMENT = 'Gross drug cost per claim in USD.',
    prescriber_count AS COUNT(DISTINCT prescription.prescriber_id)
      COMMENT = 'Number of distinct prescribers with at least one claim (Part D rows of 11 claims or more).',
    class_claims AS SUM(prescription_class.claims)
      COMMENT = 'Claims of products in a therapeutic class (including narrower classes). Filter or group by one class.',
    class_drug_cost AS SUM(prescription_class.drug_cost)
      COMMENT = 'Gross drug cost in USD of products in a therapeutic class. Filter or group by one class.',
    class_cost_per_claim AS SUM(prescription_class.drug_cost) / NULLIF(SUM(prescription_class.claims), 0)
      COMMENT = 'Gross drug cost per claim in USD within a therapeutic class.',
    class_cost_per_30day_fill AS SUM(prescription_class.drug_cost) / NULLIF(SUM(prescription_class.fills_30day), 0)
      COMMENT = 'Gross drug cost per 30-day fill in USD within a therapeutic class: compares classes fairly when fill lengths differ.',
    sglt2_claims AS SUM(CASE WHEN prescription_class.class_id = 'SGLT2Inhibitor' THEN prescription_class.claims ELSE 0 END)
      COMMENT = 'Claims of products in the class Sodium-glucose co-transporter 2 (SGLT2) inhibitors (from the definition of dm:SGLT2Prescriber).',
    glp1_claims AS SUM(CASE WHEN prescription_class.class_id = 'GLP1ReceptorAgonist' THEN prescription_class.claims ELSE 0 END)
      COMMENT = 'Claims of products in the class Glucagon-like peptide-1 (GLP-1) analogues, including dual GIP/GLP-1 agonists (from the definition of dm:GLP1Prescriber).',
    sglt2_share_vs_glp1 AS SUM(CASE WHEN prescription_class.class_id = 'SGLT2Inhibitor' THEN prescription_class.claims ELSE 0 END) / NULLIF(SUM(CASE WHEN prescription_class.class_id = 'SGLT2Inhibitor' THEN prescription_class.claims ELSE 0 END) + SUM(CASE WHEN prescription_class.class_id = 'GLP1ReceptorAgonist' THEN prescription_class.claims ELSE 0 END), 0)
      COMMENT = 'SGLT2 inhibitor claims as a fraction of SGLT2 inhibitor plus GLP-1 receptor agonist claims (0 to 1).',
    company_claims AS SUM(prescription_class_company.claims)
      COMMENT = 'Claims of products by a manufacturer within a therapeutic class. Filter or group by one class. A product with two marketing authorization holders counts fully for each, so do not divide by the sum over companies.',
    company_claims_allocated AS SUM(prescription_class_company.claims_allocated)
      COMMENT = 'Claims by manufacturer within a therapeutic class, with a product''s claims split equally among its marketing authorization holders: the companies of a class add up to the class''s claims. Market share = company_claims_allocated / its sum over all companies of the class.',
    company_drug_cost AS SUM(prescription_class_company.drug_cost)
      COMMENT = 'Gross drug cost in USD by manufacturer within a therapeutic class.'
  )
  COMMENT = 'Type 2 diabetes drug prescribing, generated from the diabetes-market ontology 0.5.2. Medicare Part D, Connecticut, data year 2024: mostly people aged 65 and over. Counts are claims (fills and refills), not patients. CMS omits prescriber/product rows with fewer than 11 claims. Costs are gross, before rebates. Prescribers are pseudonyms; report aggregates only.'
  AI_SQL_GENERATION 'Use total_claims and total_drug_cost for overall volume. For anything by therapeutic class use the class_* metrics and filter or group by one class: a combination product counts in every class it belongs to, so class figures never add up to the total. ''By drug class'' means therapeutic_class.is_drug_class = TRUE. Cost comparisons between classes: also show class_cost_per_30day_fill, the fair comparison when fill lengths differ. For market shares by company divide company_claims_allocated by its sum over all companies of the class. Names exist in English, Japanese (*_ja) and Chinese (*_zh): answer with the names in the language of the question.'
  AI_VERIFIED_QUERIES (
    sglt2_vs_glp1_by_specialty AS (
      QUESTION 'What share of SGLT2 inhibitor plus GLP-1 receptor agonist claims are SGLT2 inhibitors, by prescriber specialty?'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION TRUE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.DIABETES_MARKET DIMENSIONS specialty.specialty_name METRICS sglt2_claims, glp1_claims, sglt2_share_vs_glp1) ORDER BY sglt2_claims + glp1_claims DESC'
    ),
    cost_per_claim_by_drug_class AS (
      QUESTION 'What is the cost per claim and per 30-day fill by drug class, for single-ingredient products?'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION TRUE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.DIABETES_MARKET DIMENSIONS therapeutic_class.class_name METRICS class_claims, class_drug_cost, class_cost_per_claim, class_cost_per_30day_fill WHERE therapeutic_class.is_drug_class AND NOT product.is_combination) ORDER BY class_cost_per_30day_fill DESC'
    ),
    market_share_by_manufacturer AS (
      QUESTION 'What is each manufacturer''s share of SGLT2 inhibitor and GLP-1 receptor agonist claims?'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION FALSE
      SQL 'SELECT class_name, manufacturer, company_claims, company_claims_allocated / SUM(company_claims_allocated) OVER (PARTITION BY class_name) AS claim_share FROM SEMANTIC_VIEW(GLP.SEMANTIC.DIABETES_MARKET DIMENSIONS therapeutic_class.class_name, prescription_class_company.manufacturer METRICS company_claims, company_claims_allocated WHERE prescription_class_company.class_id IN (''SGLT2Inhibitor'', ''GLP1ReceptorAgonist'')) ORDER BY class_name, claim_share DESC'
    ),
    sglt2_by_specialty_ja AS (
      QUESTION 'SGLT2阻害薬を処方している専門分野は？'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION TRUE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.DIABETES_MARKET DIMENSIONS specialty.specialty_name_ja METRICS class_claims WHERE therapeutic_class.class_name_ja = ''SGLT2阻害薬'') ORDER BY class_claims DESC LIMIT 10'
    ),
    prescriber_overlap AS (
      QUESTION 'How many prescribers write SGLT2 inhibitors, GLP-1 receptor agonists, or both?'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION FALSE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.DIABETES_MARKET DIMENSIONS prescriber.is_sglt2_prescriber, prescriber.is_glp1_prescriber METRICS prescriber_count) ORDER BY 1, 2'
    )
  );
